#![allow(clippy::excessive_precision)]

use thermopack_rs::{Cpa, Phase};

#[test]
fn test_cpa_pure_h2o_states() {
    let eos = Cpa::new(&["H2O"]).expect("failed to load H2O");
    assert_eq!(eos.num_components(), 1);

    // Point: T = 373.15 K, rho = 50.0 mol/m^3 (vapor)
    let prep = eos.prepare(373.15, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(50.0).unwrap();
    assert!(
        (jet.pressure - 1.4843960165512856e+05).abs() < 1.4843960165512857e+02,
        "P diff: {}",
        (jet.pressure - 1.4843960165512856e+05).abs()
    );
    let st = prep.state(50.0).unwrap();
    assert!(
        (st.ln_phi[0] - -4.2998452674473803e-02).abs() < 1e-5,
        "lnphi diff: {}",
        (st.ln_phi[0] - -4.2998452674473803e-02).abs()
    );

    // Point: T = 373.15 K, rho = 1000.0 mol/m^3 (dense vapor)
    let prep = eos.prepare(373.15, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(1000.0).unwrap();
    assert!(
        (jet.pressure - 1.4496606622214802e+06).abs() < 1.4496606622214802e+03,
        "P diff: {}",
        (jet.pressure - 1.4496606622214802e+06).abs()
    );
    let st = prep.state(1000.0).unwrap();
    assert!(
        (st.ln_phi[0] - -4.4673785048144954e-01).abs() < 1e-5,
        "lnphi diff: {}",
        (st.ln_phi[0] - -4.4673785048144954e-01).abs()
    );

    // Point: T = 500.0 K, rho = 500.0 mol/m^3 (supercritical gas)
    let prep = eos.prepare(500.00, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(500.0).unwrap();
    assert!(
        (jet.pressure - 1.8531103403871313e+06).abs() < 1.8531103403871314e+03,
        "P diff: {}",
        (jet.pressure - 1.8531103403871313e+06).abs()
    );
    let st = prep.state(500.0).unwrap();
    assert!(
        (st.ln_phi[0] - -1.0688525122084741e-01).abs() < 1e-5,
        "lnphi diff: {}",
        (st.ln_phi[0] - -1.0688525122084741e-01).abs()
    );
}

#[test]
fn test_cpa_pure_h2o_volume_and_saturation() {
    let eos = Cpa::new(&["H2O"]).expect("failed to load H2O");
    let prep = eos.prepare(373.15, &[1.0]).unwrap();
    let p_target = 101325.0; // 1 atm
    let vv = prep.volume(p_target, Phase::Vapor).unwrap();
    let jet_v = prep.pressure_and_derivatives(1.0 / vv).unwrap();
    assert!((jet_v.pressure - p_target).abs() < 0.2);
    let vl = prep.volume(p_target, Phase::Liquid).unwrap();
    let jet_l = prep.pressure_and_derivatives(1.0 / vl).unwrap();
    assert!((jet_l.pressure - p_target).abs() < 0.2);
    assert!(vl < vv);

    // Saturation pressure at 373.15 K: reference P_sat = 1.002195e+05 Pa
    let sat = prep.saturation_pressure(373.15).unwrap();
    assert!(
        (sat.pressure - 1.00219534e+05).abs() / 1.00219534e+05 < 1e-3,
        "sat P diff: {}",
        (sat.pressure - 1.00219534e+05).abs()
    );
    assert!((sat.liquid_volume - 1.89774436e-05).abs() / 1.89774436e-05 < 1e-2);
    assert!((sat.vapor_volume - 3.00580034e-02).abs() / 3.00580034e-02 < 1e-2);
}

#[test]
fn test_cpa_pure_etoh_states() {
    let eos = Cpa::new(&["ETOH"]).expect("failed to load ETOH");
    // Point: T = 300.0 K, rho = 20.0 mol/m^3 (vapor)
    let prep = eos.prepare(300.0, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(20.0).unwrap();
    assert!((jet.pressure - 4.5526649942860728e+04).abs() < 4.5526649942860729e+01);
    let st = prep.state(20.0).unwrap();
    assert!((st.ln_phi[0] - -9.0096634430718830e-02).abs() < 1e-5);

    // Point: T = 350.0 K, rho = 100.0 mol/m^3 (dense vapor)
    let prep = eos.prepare(350.0, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(100.0).unwrap();
    assert!((jet.pressure - 2.5092164829298592e+05).abs() < 2.5092164829298594e+02);
    let st = prep.state(100.0).unwrap();
    assert!((st.ln_phi[0] - -1.4032011837647132e-01).abs() < 1e-5);

    // Point: T = 400.0 K, rho = 500.0 mol/m^3 (dense gas)
    let prep = eos.prepare(400.0, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(500.0).unwrap();
    assert!((jet.pressure - 1.1835230889648197e+06).abs() < 1.1835230889648196e+03);
    let st = prep.state(500.0).unwrap();
    assert!((st.ln_phi[0] - -2.7589071150430183e-01).abs() < 1e-5);
}

