#[test]
fn test_cpa_binary_h2o_co2() {
    let eos = Cpa::new(&["H2O", "CO2"]).expect("failed to load H2O,CO2");
    assert_eq!(eos.num_components(), 2);
    let prep = eos.prepare(350.0, &[0.7, 0.3]).unwrap();
    let jet = prep.pressure_and_derivatives(1000.0).unwrap();
    assert!((jet.pressure - 1.7515331215770424e+06).abs() < 1.7515331215770425e+03);
    let st = prep.state(1000.0).unwrap();
    assert!((st.ln_phi[0] - -7.1679721323823187e-01).abs() < 1e-4);
    assert!((st.ln_phi[1] - 3.7903932821737008e-01).abs() < 1e-4);
}

#[test]
fn test_cpa_binary_h2o_etoh() {
    let eos = Cpa::new(&["H2O", "ETOH"]).expect("failed to load H2O,ETOH");
    assert_eq!(eos.num_components(), 2);
    assert!((eos.get_kij(0, 1) - (-0.11)).abs() < 1e-5);

    let prep = eos.prepare(360.0, &[0.4, 0.6]).unwrap();
    let jet = prep.pressure_and_derivatives(2000.0).unwrap();
    assert!(
        (jet.pressure - 3.4575014908580761e+05).abs() < 3.4575014908580761e+02,
        "P diff: {}",
        (jet.pressure - 3.4575014908580761e+05).abs()
    );
    let st = prep.state(2000.0).unwrap();
    assert!((st.ln_phi[0] - 6.0171293868469133e-01).abs() < 1e-4);
    assert!((st.ln_phi[1] - 4.3398937260445880e-01).abs() < 1e-4);
}
